92	export class JetEngine extends SceneObject<JetEngineTweenProps> {
93	  private static readonly DEFAULT_INTENSITY = 0.78;
94	  private static readonly DEFAULT_LENGTH = 2.4;
95	  private static readonly DEFAULT_NOZZLE_RADIUS = 0.028;
96	  private static readonly DEFAULT_NOZZLE_GAP = 2.2;
97	  private static readonly DEFAULT_INNER_RGB: RGB = [0.4, 0.75, 1.0];
98	  private static readonly DEFAULT_OUTER_RGB: RGB = [1.0, 0.92, 0.78];
99	  /** Outer shell length = core length × this (was 3.2 / 2.4 in author defaults). */
100	  private static readonly PARENT_LENGTH_RATIO = 3.2 / 2.4;
101	  private static readonly SIM_BURST_SPEED = 1.2;
102	  private static readonly SIM_BURST_AMP_MIN = 0.08;
103	  private static readonly SIM_BURST_AMP_MAX = 0.22;
104	  private static readonly SIM_SMOOTHING = 0.14;
105	  private static readonly TIP_MUL_INNER = 0.42;
106	  private static readonly TIP_MUL_OUTER = 0.88;
107	  /** Slightly above `Rocket` billboard flame (`renderOrder` 5). */
108	  private static readonly MESH_RENDER_ORDER = 6;
109	  private _options: Partial<JetEngineObjectOptions> = {};
110	  private _cfg: JetEngineResolvedConfig = JetEngine.resolveConfig({});
111	  private _sim: CombustionSim = new CombustionSim(
112	    this._cfg,
113	    JetEngine.easeOutExpo,
114	    JetEngine.easeOutCubic,
115	  );
116	
117	  private static sameRGB(a: RGB, b: RGB): boolean {
118	    return a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
119	  }
120	
121	  private static needsRebuild(
122	    prev: JetEngineResolvedConfig,
123	    next: JetEngineResolvedConfig,
124	  ): boolean {
125	    return (
126	      prev.nozzleRadius !== next.nozzleRadius ||
127	      prev.nozzleGap !== next.nozzleGap ||
128	      prev.baseLength !== next.baseLength ||
129	      prev.innerNoiseSpeed !== next.innerNoiseSpeed ||
130	      prev.parentNoiseSpeed !== next.parentNoiseSpeed ||
131	      prev.turbulence !== next.turbulence ||
132	      !JetEngine.sameRGB(prev.innerColor.top, next.innerColor.top) ||
133	      !JetEngine.sameRGB(prev.parentColor.top, next.parentColor.top)
134	    );
135	  }
136	
137	  private static darkenTip(c: RGB, mul: number): RGB {
138	    return [
139	      Math.min(1, c[0] * mul),
140	      Math.min(1, c[1] * mul),
141	      Math.min(1, c[2] * mul),
142	    ];
143	  }
144	
145	  private static glslVec3(c: RGB): string {
146	    return `vec3(${c[0].toFixed(4)},${c[1].toFixed(4)},${c[2].toFixed(4)})`;
147	  }
148	
149	  private static applyShaderTemplate(
150	    template: string,
151	    values: Record<string, string>,
152	  ): string {
153	    let out = template;
154	    for (const [key, value] of Object.entries(values)) {
155	      out = out.split(`__${key}__`).join(value);
156	    }
157	    return out;
158	  }
159	
160	  private static easeOutExpo(x: number): number {
161	    return x === 1 ? 1 : 1 - Math.pow(2, -10 * x);
162	  }
163	
164	  private static easeOutCubic(x: number): number {
165	    return 1 - Math.pow(1 - x, 3);
166	  }
167	
168	  private static resolveConfig(
169	    o: Partial<JetEngineObjectOptions>,
170	  ): JetEngineResolvedConfig {
171	    const intensity =
172	      typeof o.intensity === "number"
173	        ? Math.max(0, Math.min(1, o.intensity))
174	        : JetEngine.DEFAULT_INTENSITY;
175	    const gap =
176	      typeof o.nozzleGap === "number" && Number.isFinite(o.nozzleGap)
177	        ? o.nozzleGap
178	        : JetEngine.DEFAULT_NOZZLE_GAP;
179	    const length =
180	      typeof o.length === "number" && Number.isFinite(o.length)
181	        ? o.length
182	        : JetEngine.DEFAULT_LENGTH;
183	    const noise =
184	      typeof o.noise === "number" && Number.isFinite(o.noise)
185	        ? Math.max(0, o.noise)
186	        : 1;
187	    const bloom =
188	      typeof o.bloom === "number" && Number.isFinite(o.bloom)
189	        ? Math.max(0, o.bloom)
190	        : 1;
191	    const innerTop = o.innerColor ?? JetEngine.DEFAULT_INNER_RGB;
192	    const outerTop = o.outerColor ?? JetEngine.DEFAULT_OUTER_RGB;
193	    const nr =
194	      typeof o.nozzleRadius === "number" && Number.isFinite(o.nozzleRadius)
195	        ? o.nozzleRadius
196	        : JetEngine.DEFAULT_NOZZLE_RADIUS;
197	
198	    return {
199	      nozzleRadius: nr,
200	      nozzleGapX: gap,
201	      nozzleGapZ: gap,
202	      nozzleGap: gap,
203	      baseLength: length,
204	      parentLength: length * JetEngine.PARENT_LENGTH_RATIO,
205	      burstSpeed: JetEngine.SIM_BURST_SPEED,
206	      baseIdle: intensity,
207	      burstAmpMin: JetEngine.SIM_BURST_AMP_MIN,
208	      burstAmpMax: JetEngine.SIM_BURST_AMP_MAX,
209	      smoothing: JetEngine.SIM_SMOOTHING,
210	      innerNoiseSpeed: noise,
211	      parentNoiseSpeed: noise * 0.85,
212	      turbulence: noise,
213	      innerColor: {
214	        top: innerTop,
215	        tip: JetEngine.darkenTip(innerTop, JetEngine.TIP_MUL_INNER),
216	      },
217	      parentColor: {
218	        top: outerTop,
219	        tip: JetEngine.darkenTip(outerTop, JetEngine.TIP_MUL_OUTER),
220	      },
221	      innerBloom: bloom,
222	      parentBloom: bloom * 0.92,
223	    };
224	  }
225	
226	  private static innerVertGLSL(cfg: JetEngineResolvedConfig): string {
227	    return JetEngine.applyShaderTemplate(innerVertRaw as string, {
228	      NOISE_GLSL: noiseRaw as string,
229	      INNER_RS: (2.8 * cfg.innerNoiseSpeed).toFixed(3),
230	      INNER_LS: (2.2 * cfg.innerNoiseSpeed).toFixed(3),
231	      INNER_RT: (0.1 * cfg.turbulence).toFixed(4),
232	      INNER_LT: (0.22 * cfg.turbulence).toFixed(4),
233	    });
234	  }
235	
236	  private static innerFragGLSL(cfg: JetEngineResolvedConfig): string {
237	    const flash = JetEngine.glslVec3(
238	      cfg.innerColor.top.map((v) => Math.min(1, v + 0.2)) as RGB,
239	    );
240	    return JetEngine.applyShaderTemplate(innerFragRaw as string, {
241	      NOISE_GLSL: noiseRaw as string,
242	      INNER_FS1: (7.0 * cfg.innerNoiseSpeed).toFixed(3),
243	      INNER_FS2: (4.5 * cfg.innerNoiseSpeed).toFixed(3),
244	      INNER_C_TOP: JetEngine.glslVec3(cfg.innerColor.top),
245	      INNER_C_TIP: JetEngine.glslVec3(cfg.innerColor.tip),
246	      INNER_FLASH: flash,
247	    });
248	  }
249	
250	  private static parentVertGLSL(cfg: JetEngineResolvedConfig): string {
251	    return JetEngine.applyShaderTemplate(parentVertRaw as string, {
252	      NOISE_GLSL: noiseRaw as string,
253	      PARENT_RS: (2.4 * cfg.parentNoiseSpeed).toFixed(3),
254	      PARENT_LS: (1.8 * cfg.parentNoiseSpeed).toFixed(3),
255	      PARENT_RT: (0.18 * cfg.turbulence).toFixed(4),
256	      PARENT_LT: (0.3 * cfg.turbulence).toFixed(4),
257	    });
258	  }
259	
260	  private static parentFragGLSL(cfg: JetEngineResolvedConfig): string {
261	    return JetEngine.applyShaderTemplate(parentFragRaw as string, {
262	      NOISE_GLSL: noiseRaw as string,
263	      PARENT_FS1: (1.2 * cfg.parentNoiseSpeed).toFixed(3),
264	      PARENT_FS2: (0.7 * cfg.parentNoiseSpeed).toFixed(3),
265	      PARENT_C_TOP: JetEngine.glslVec3(cfg.parentColor.top),
266	      PARENT_C_TIP: JetEngine.glslVec3(cfg.parentColor.tip),
267	    });
268	  }
269	  private _inner: JetEngineRecord[] = [];
270	  private _parent: JetEngineRecord | null = null;
271	  private _innerGeo: THREE.BufferGeometry | null = null;
272	  private _built = false;
273	  private _intensity = JetEngine.DEFAULT_INTENSITY;
274	
275	  setOptions(props: Partial<JetEngineObjectOptions> | undefined): this {
276	    if (props != null) this._options = { ...this._options, ...props };
277	    return this;
278	  }
279	
280	  override getAnimationTarget(): THREE.Object3D | null {
281	    return this.getTimelineRoot();
282	  }
283	
284	  override getTweenApplyMode(): "mergeAndSync" {
285	    return "mergeAndSync";
286	  }
287	
288	  protected override getOptions(): Record<string, unknown> {
289	    return this._options;
290	  }
291	
292	  protected override applyVisibility(visible: boolean): void {
293	    const root = this.getTimelineRoot();
294	    if (!root) return;
295	    root.visible = visible;
296	  }
297	
298	  protected override syncFromOptions(): void {
299	    const nextCfg = JetEngine.resolveConfig(this._options);
300	    this._intensity = Math.max(0, Math.min(1, nextCfg.baseIdle));
301	    const shouldRebuild =
302	      this._built && JetEngine.needsRebuild(this._cfg, nextCfg);
303	    this._cfg = nextCfg;
304	    this._sim.applyConfig(this._cfg);
305	    if (shouldRebuild) this._build();
306	  }
307	
308	  override runObject(): void {
309	    const ctx = this._context;
310	    if (!ctx?.scene) return;
311	
312	    const root = this.ensureTimelineRoot("jetEngineRoot");
313	    if (!root) return;
314	    this._cfg = JetEngine.resolveConfig(this._options);
315	    this._intensity = Math.max(0, Math.min(1, this._cfg.baseIdle));
316	    this._sim.applyConfig(this._cfg);
317	    this._build();
318	
319	    const attachTo = this._options.attachTo;
320	    const offset = this._options.offset ?? { x: 0, y: 0, z: 0 };
321	    const p = this._options.position ?? { x: 0, y: 0, z: 0 };
322	    const r = this._options.rotation ?? { x: 0, y: 0, z: 0 };
323	    const s = this._options.scale ?? { x: 1, y: 1, z: 1 };
324	
325	    if (attachTo && typeof ctx.getObject === "function") {
326	      const target = ctx.getObject(attachTo);
327	      if (target instanceof THREE.Object3D) {
328	        target.add(root);
329	        root.position.set(offset.x ?? 0, offset.y ?? 0, offset.z ?? 0);
330	      } else {
331	        root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
332	      }
333	    } else {
334	      root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
335	    }
336	
337	    Helpers.applyRotationDeg(root, r);
338	    root.scale.set(s.x ?? 1, s.y ?? 1, s.z ?? 1);
339	    root.traverse((child) => {
340	      child.layers.set(THREE_LAYER_ROCKET);
341	    });
342	    this._built = true;
343	  }
344	
345	  override runUpdate(deltaTime: number): void {
346	    if (!this._built) return;
347	    const root = this.getTimelineRoot();
348	    if (!root?.visible) return;
349	    const camera = this._context?.camera as THREE.Camera | undefined;
350	    if (!camera) return;
351	
352	    const { flameLen, throttle, elapsed } = this._sim.update(deltaTime);
353	    const flameLenScaled = flameLen * this._intensity;
354	    const throttleScaled = throttle * this._intensity;
355	    for (const eng of this._inner) {
356	      eng.group.scale.y = this._cfg.baseLength * flameLenScaled;
357	      eng.mat.uniforms.uTime.value = elapsed;
358	      eng.mat.uniforms.uFlameLen.value = flameLenScaled;
359	      eng.mat.uniforms.uThrottle.value = throttleScaled;
360	      for (const b of eng.blooms) {
361	        b.mesh.quaternion.copy(camera.quaternion);
362	        b.mat.uniforms.uTime.value = elapsed;
363	        b.mat.uniforms.uIntensity.value =
364	          b.baseIntensity *
365	          this._cfg.innerBloom *
366	          throttleScaled *
367	          (0.8 + flameLenScaled * 0.5);
368	        b.mesh.position.y = b.yOffset;
369	      }
370	    }
371	
372	    const parent = this._parent;
373	    if (!parent) return;
374	    parent.group.scale.y = this._cfg.parentLength * flameLenScaled;
375	    parent.mat.uniforms.uTime.value = elapsed;
376	    parent.mat.uniforms.uFlameLen.value = flameLenScaled;
377	    parent.mat.uniforms.uThrottle.value = throttleScaled;
378	    for (const b of parent.blooms) {
379	      b.mesh.quaternion.copy(camera.quaternion);
380	      b.mat.uniforms.uTime.value = elapsed;
381	      b.mat.uniforms.uIntensity.value =
