582	  private _buildBlooms(
583	    parent: THREE.Group,
584	    layers: Array<{
585	      color: RGB;
586	      radius: number;
587	      size: number;
588	      baseI: number;
589	      y: number;
590	    }>,
591	  ): JetEngineBloomLayer[] {
592	    return layers.map((l, index) => {
593	      const geo = new THREE.PlaneGeometry(l.size, l.size);
594	      const mat = new THREE.ShaderMaterial({
595	        uniforms: {
596	          uTime: { value: 0 },
597	          uColor: { value: new THREE.Color(...l.color) },
598	          uIntensity: { value: l.baseI },
599	          uRadius: { value: l.radius },
600	        },
601	        vertexShader: bloomVertRaw as string,
602	        fragmentShader: bloomFragRaw as string,
603	        transparent: true,
604	        depthWrite: false,
605	        blending: THREE.AdditiveBlending,
606	        side: THREE.DoubleSide,
607	      });
608	      this.registerShader({
609	        key: this.createShaderKey(`bloom.${parent.uuid}.${index}`),
610	        ownerId: this.getShaderOwnerId(),
611	        material: mat,
612	        autoResolution: false,
613	      });
614	      const mesh = new THREE.Mesh(geo, mat);
615	      mesh.position.y = l.y;
616	      mesh.layers.set(THREE_LAYER_ROCKET);
617	      mesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
618	      parent.add(mesh);
619	      return { mesh, mat, baseIntensity: l.baseI, yOffset: l.y };
620	    });
621	  }
